def validate_input(user_input):
    if not user_input:
        return False
    elif not user_input.replace(' ', '').isalnum():
        return False
    else:
        return True

test_cases = [
    ('Hello World', True),
    ('HelloWorld', True),
    ('Hello World123', True),
    ('Hello World!', False),
    ('', False),
    ('   ', False)
]

for test_case in test_cases:
    user_input, expected_output = test_case
    actual_output = validate_input(user_input)
    print(f'Input: {user_input}, Expected: {expected_output}, Actual: {actual_output}')
